// Normalise Payload (n8n Code node, "Run Once for All Items")
//
// Maps the inbound shapes this router understands onto one canonical alert record:
//   1. Databricks job notification webhook  {event_type: "jobs.on_failure", workspace_id, run: {run_id}, job: {job_id, name}}
//   2. Azure Monitor common alert schema    {schemaId: "azureMonitorCommonAlertSchema", data: {essentials, alertContext}}
//      (this is what an Azure Data Factory metric alert such as PipelineFailedRuns sends to a webhook)
//   3. Generic JSON from in-house checks    {source, event_type, status, pipeline, environment, message, event_id}
// Any other JSON object is kept as source "unknown" (never silently dropped): it is logged and lands
// in the LOW digest. A body that is not a JSON object throws, which fails the execution and fires the
// error workflow.

// Databricks webhooks carry a workspace id, not an environment name. In production this lookup would
// live in a config table; the ids below are the sample ids used by the simulator.
const DATABRICKS_WORKSPACES = {
  '1234567890123456': { environment: 'prod', host: 'https://adb-1234567890123456.7.azuredatabricks.net' },
  '2345678901234567': { environment: 'dev', host: 'https://adb-2345678901234567.7.azuredatabricks.net' },
};

const DATABRICKS_EVENTS = {
  'jobs.on_failure': { event_type: 'failure', status: 'FIRING', detail: 'Job run failed' },
  'jobs.on_duration_warning_threshold_exceeded': {
    event_type: 'sla_breach',
    status: 'FIRING',
    detail: 'Run exceeded the job duration warning threshold',
  },
  'jobs.on_streaming_backlog_exceeded': {
    event_type: 'sla_breach',
    status: 'FIRING',
    detail: 'Streaming backlog exceeded the configured threshold',
  },
  // A successful run resolves an earlier failure for the same job.
  'jobs.on_success': { event_type: 'failure', status: 'RESOLVED', detail: 'Job run succeeded' },
  'jobs.on_start': { event_type: 'info', status: 'FIRING', detail: 'Job run started' },
};

// Azure Data Factory metric names -> canonical event type.
const AZURE_METRIC_EVENTS = {
  PipelineFailedRuns: 'failure',
  ActivityFailedRuns: 'failure',
  TriggerFailedRuns: 'failure',
  PipelineElapsedTimeRuns: 'sla_breach',
};

const ENV_ALIASES = { prd: 'prod', production: 'prod', development: 'dev', stg: 'staging' };

function clean(value, fallback = 'unknown') {
  const text = value === undefined || value === null ? '' : String(value).trim();
  return text || fallback;
}

function envFromName(name) {
  const match = /(?:^|[-_.])(prod|prd|production|dev|development|test|qa|uat|stg|staging|sandbox)(?:$|[-_.])/i.exec(
    name || '',
  );
  if (!match) return null;
  const env = match[1].toLowerCase();
  return ENV_ALIASES[env] || env;
}

function normaliseEnv(value) {
  const env = clean(value).toLowerCase();
  return ENV_ALIASES[env] || env;
}

function isoOrNull(value) {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

// Small, dependency-free FNV-1a hash, used only to derive an id when a payload has none.
function fnv1a(text) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

function fromDatabricks(body) {
  const mapped = DATABRICKS_EVENTS[body.event_type] || { event_type: 'info', status: 'FIRING', detail: body.event_type };
  const job = body.job || {};
  const run = body.run || {};
  const workspaceId = clean(body.workspace_id);
  const workspace = DATABRICKS_WORKSPACES[workspaceId] || {};
  const runId = run.run_id === undefined || run.run_id === null ? null : String(run.run_id);
  const jobId = clean(job.job_id);
  return {
    source: 'databricks',
    source_label: 'Databricks job',
    source_event: body.event_type,
    // Databricks sends no event id; (workspace, job, run, event type) identifies one notification.
    event_id: `databricks:${workspaceId}:${jobId}:${runId || 'na'}:${body.event_type}`,
    event_type: mapped.event_type,
    status: mapped.status,
    pipeline: clean(job.name),
    environment: workspace.environment || envFromName(job.name) || 'unknown',
    run_id: runId,
    run_url: workspace.host && runId ? `${workspace.host}/jobs/${jobId}/runs/${runId}` : null,
    // The webhook does not include the error text; production would enrich it via the Jobs API (runs/get).
    error_message: mapped.detail,
    upstream_severity: null,
    occurred_at: null,
  };
}

function fromAzureMonitor(body) {
  const essentials = body.data.essentials || {};
  const context = body.data.alertContext || {};
  const condition = (context.condition && Array.isArray(context.condition.allOf) && context.condition.allOf[0]) || {};
  const dims = {};
  for (const d of condition.dimensions || []) dims[d.name] = d.value;
  const resourceId = (essentials.alertTargetIDs || [])[0] || '';
  const resourceName = clean(resourceId.split('/').pop() || (essentials.configurationItems || [])[0]);
  const metric = condition.metricName || null;
  const isDataFactory = /microsoft\.datafactory/i.test(resourceId) || /DataFactory/i.test(condition.metricNamespace || '');
  const status = essentials.monitorCondition === 'Resolved' ? 'RESOLVED' : 'FIRING';
  const custom = body.data.customProperties || {};
  let detail = essentials.description || null;
  if (!detail && metric) {
    detail = `${metric} ${condition.operator || ''} ${condition.threshold ?? ''}`.replace(/\s+/g, ' ').trim();
    if (condition.metricValue !== undefined) detail += ` (observed ${condition.metricValue})`;
    if (dims.FailureType) detail += `, FailureType=${dims.FailureType}`;
  }
  return {
    source: 'azure_monitor',
    source_label: isDataFactory ? 'ADF pipeline' : 'Azure resource',
    source_event: `${essentials.signalType || 'Unknown'}/${metric || essentials.alertRule || 'alert'}`,
    // Fired and Resolved notifications share alertId, so the status is part of the idempotency key.
    event_id: `azure:${essentials.alertId || fnv1a(JSON.stringify(body))}:${status}`,
    event_type: AZURE_METRIC_EVENTS[metric] || (/fail/i.test(essentials.alertRule || '') ? 'failure' : 'info'),
    status,
    pipeline: clean(dims.Name || dims.PipelineName || essentials.alertRule),
    environment: normaliseEnv(custom.environment || envFromName(resourceName) || 'unknown'),
    run_id: dims.RunId || null,
    run_url: resourceId ? `https://portal.azure.com/#resource${resourceId}/overview` : null,
    error_message: detail,
    upstream_severity: essentials.severity || null,
    occurred_at: isoOrNull(status === 'RESOLVED' ? essentials.resolvedDateTime : essentials.firedDateTime),
    resource: resourceName,
    alert_rule: essentials.alertRule || null,
  };
}

function fromGeneric(body) {
  const source = clean(body.source).toLowerCase().replace(/[^a-z0-9_.-]+/g, '_');
  const status = String(body.status || 'FIRING').toUpperCase() === 'RESOLVED' ? 'RESOLVED' : 'FIRING';
  const eventType = ['failure', 'sla_breach'].includes(body.event_type) ? body.event_type : 'info';
  return {
    source,
    source_label: clean(body.source_label, 'Pipeline'),
    source_event: body.event_type || null,
    event_id: `${source}:${body.event_id ? String(body.event_id) : fnv1a(JSON.stringify(body))}`,
    event_type: eventType,
    status,
    pipeline: clean(body.pipeline),
    environment: normaliseEnv(body.environment || envFromName(body.pipeline) || 'unknown'),
    run_id: body.run_id === undefined || body.run_id === null ? null : String(body.run_id),
    run_url: body.run_url || null,
    error_message: body.message || body.error || null,
    upstream_severity: body.severity || null,
    occurred_at: isoOrNull(body.occurred_at),
  };
}

function fromUnknown(body) {
  const text = JSON.stringify(body);
  return {
    source: 'unknown',
    source_label: 'Unrecognised sender',
    source_event: null,
    event_id: `unknown:${fnv1a(text)}`,
    event_type: 'info',
    status: 'FIRING',
    pipeline: 'unknown',
    environment: 'unknown',
    run_id: null,
    run_url: null,
    error_message: `Unrecognised payload: ${text.slice(0, 300)}`,
    upstream_severity: null,
    occurred_at: null,
  };
}

function normalise(body, receivedAt) {
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    throw new Error('Unsupported payload: expected a JSON object in the request body');
  }
  let alert;
  if (typeof body.event_type === 'string' && body.event_type.startsWith('jobs.') && body.job) {
    alert = fromDatabricks(body);
  } else if (body.schemaId === 'azureMonitorCommonAlertSchema' && body.data && body.data.essentials) {
    alert = fromAzureMonitor(body);
  } else if (body.source && body.pipeline) {
    alert = fromGeneric(body);
  } else {
    alert = fromUnknown(body);
  }
  alert.fingerprint = [alert.source, alert.environment, alert.pipeline, alert.event_type].join(':').toLowerCase();
  alert.received_at = receivedAt;
  alert.raw = body;
  return alert;
}

const receivedAt = new Date().toISOString();
return $input.all().map((item) => ({ json: normalise(item.json.body, receivedAt) }));

// Classify Severity (n8n Code node, "Run Once for All Items")
//
// Ordered rules, first match wins. Each alert gets a severity, the id and reason of the rule that
// matched (so every routing decision can be explained), a route and a rule-based summary.
//
//   severity  -> route
//   CRITICAL  -> PAGE    Slack + Jira + email to on-call
//   HIGH      -> NOTIFY  Slack + Jira
//   LOW       -> DIGEST  daily digest email
//   INFO      -> RESOLVE recovery events (Slack "resolved" if an alert was open)

// Business tier per pipeline / job (1 = revenue or regulatory impact). Unlisted pipelines are tier 3.
// In production this would be a config table owned by the data platform team.
const PIPELINE_TIERS = {
  nightly_sales_etl: 1,
  pl_load_finance_gl: 1,
  'gold.sales_daily': 1,
  pl_ingest_crm_accounts: 2,
  customer_360_refresh: 2,
  pl_refresh_marketing_lookup: 3,
};

const NON_PROD = new Set(['dev', 'test', 'qa', 'uat', 'staging', 'sandbox']);

const ROUTE_BY_SEVERITY = { CRITICAL: 'PAGE', HIGH: 'NOTIFY', LOW: 'DIGEST', INFO: 'RESOLVE' };

const RULES = [
  {
    id: 'R1_recovery',
    when: (a) => a.status === 'RESOLVED',
    severity: 'INFO',
    reason: 'Recovery event, closes any open alert for the same pipeline',
  },
  {
    id: 'R2_non_prod',
    when: (a) => NON_PROD.has(a.environment),
    severity: 'LOW',
    reason: 'Non-production environment',
  },
  {
    id: 'R3_tier1_failure',
    when: (a) => a.event_type === 'failure' && a.tier === 1,
    severity: 'CRITICAL',
    reason: 'Tier-1 pipeline failed in production',
  },
  {
    id: 'R4_upstream_sev0_sev1',
    when: (a) => a.event_type !== 'info' && ['Sev0', 'Sev1'].includes(a.upstream_severity),
    severity: 'CRITICAL',
    reason: 'Azure Monitor alert rule is Sev0/Sev1',
  },
  {
    id: 'R5_prod_failure',
    when: (a) => a.event_type === 'failure',
    severity: 'HIGH',
    reason: 'Production pipeline failure',
  },
  {
    id: 'R6_sla_breach_tier1_2',
    when: (a) => a.event_type === 'sla_breach' && a.tier <= 2,
    severity: 'HIGH',
    reason: 'SLA breach on a tier-1/2 pipeline',
  },
  {
    id: 'R7_default_low',
    when: () => true,
    severity: 'LOW',
    reason: 'Low-impact or informational event',
  },
];

function describe(alert) {
  if (alert.status === 'RESOLVED') return 'recovered';
  if (alert.event_type === 'failure') return 'failed';
  if (alert.event_type === 'sla_breach') return 'breached its SLA';
  return 'reported an event';
}

function classify(alert) {
  const tier = Object.prototype.hasOwnProperty.call(PIPELINE_TIERS, alert.pipeline) ? PIPELINE_TIERS[alert.pipeline] : 3;
  const ctx = { ...alert, tier };
  const rule = RULES.find((r) => r.when(ctx));
  const run = alert.run_id ? ` (run ${alert.run_id})` : '';
  return {
    ...alert,
    tier,
    severity: rule.severity,
    severity_rule: rule.id,
    severity_reason: rule.reason,
    route: ROUTE_BY_SEVERITY[rule.severity],
    summary: `[${rule.severity}] ${alert.source_label} ${alert.pipeline} ${describe(alert)} in ${alert.environment}${run}. ${rule.reason}.`,
    summary_source: 'rules',
  };
}

return $input.all().map((item) => ({ json: classify(item.json) }));

// Attach Summary (n8n Code node, "Run Once for All Items")
//
// The "LLM Summary (optional)" node before this one is disabled by default, so n8n passes the
// classified alert straight through and the rule-based summary is kept. If the LLM node is enabled
// and returns an OpenAI-style chat completion, its text replaces the summary. If the LLM call fails
// (the node is set to continue on error) the rule-based summary is kept: the LLM is advisory and is
// never on the critical path of an alert.

const classified = $('Classify Severity').all();

function llmText(json) {
  const choice = json && Array.isArray(json.choices) ? json.choices[0] : null;
  const text = choice && choice.message ? choice.message.content : null;
  return typeof text === 'string' && text.trim() ? text.trim().slice(0, 600) : null;
}

return $input.all().map((item, index) => {
  const alert = classified[index] ? classified[index].json : item.json;
  const text = llmText(item.json);
  return {
    json: {
      ...alert,
      summary: text || alert.summary,
      summary_source: text ? 'llm' : 'rules',
    },
  };
});

// Build Notifications (n8n Code node, "Run Once for All Items")
//
// Input: the row returned by alerting.register_alert() (alert_id, decision, occurrence, is_replay,
// window_started_at, alert). Output: the alert plus ready-to-send Slack, Jira and email payloads and
// the `action` the router switches on. Environment-specific values (Jira project key, issue type,
// addresses) are added in the sending nodes from env vars, so this code stays pure and testable.

const EMOJI = { CRITICAL: ':rotating_light:', HIGH: ':warning:', LOW: ':information_source:', INFO: ':white_check_mark:' };
const NOTIFYING = new Set(['PAGE', 'NOTIFY', 'RESOLVE', 'DIGEST']);

function escapeHtml(value) {
  return String(value === undefined || value === null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function verb(a) {
  if (a.status === 'RESOLVED') return 'recovered';
  if (a.event_type === 'failure') return 'failed';
  if (a.event_type === 'sla_breach') return 'breached SLA';
  return 'event';
}

function slackMessage(a) {
  const resolved = a.decision === 'RESOLVE';
  const title = resolved
    ? `RESOLVED: ${a.pipeline} (${a.environment})`
    : `${a.severity}: ${a.pipeline} ${verb(a)} (${a.environment})`;
  const run = a.run_url ? `<${a.run_url}|${a.run_id || 'open'}>` : a.run_id || '-';
  return {
    text: `${EMOJI[resolved ? 'INFO' : a.severity] || ''} ${title}`.trim(),
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: title.slice(0, 150) } },
      {
        type: 'section',
        fields: [
          { type: 'mrkdwn', text: `*Source*\n${a.source_label}` },
          { type: 'mrkdwn', text: `*Environment*\n${a.environment}` },
          { type: 'mrkdwn', text: `*Run*\n${run}` },
          { type: 'mrkdwn', text: `*Alert id*\n${a.alert_id}` },
        ],
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `*Summary:* ${a.summary}\n*Detail:* ${a.error_message || '-'}\n*Rule:* ${a.severity_rule}`,
        },
      },
      { type: 'context', elements: [{ type: 'mrkdwn', text: `fingerprint \`${a.fingerprint}\`` }] },
    ],
  };
}

function jiraFields(a) {
  const description = [
    a.summary,
    '',
    `*Source:* ${a.source_label} (${a.source_event || a.source})`,
    `*Pipeline:* ${a.pipeline}`,
    `*Environment:* ${a.environment}`,
    `*Run:* ${a.run_id || '-'} ${a.run_url || ''}`.trim(),
    `*Detail:* ${a.error_message || '-'}`,
    `*Severity rule:* ${a.severity_rule} - ${a.severity_reason}`,
    `*Fingerprint:* ${a.fingerprint}`,
    `*Alert id:* ${a.alert_id}`,
  ].join('\n');
  return {
    summary: `[${a.severity}] ${a.pipeline} ${verb(a)} (${a.environment})`.slice(0, 250),
    description,
    priority: { name: a.severity === 'CRITICAL' ? 'Highest' : 'High' },
    labels: ['dataops-alert', `severity-${String(a.severity).toLowerCase()}`, `source-${a.source}`],
  };
}

function email(a) {
  const runCell = a.run_url
    ? `<a href="${escapeHtml(a.run_url)}">${escapeHtml(a.run_id || a.run_url)}</a>`
    : escapeHtml(a.run_id || '-');
  const rows = [
    ['Severity', escapeHtml(`${a.severity} (rule ${a.severity_rule})`), `${a.severity} (rule ${a.severity_rule})`],
    ['Why', escapeHtml(a.severity_reason), a.severity_reason],
    ['Source', escapeHtml(`${a.source_label} - ${a.source_event || a.source}`), `${a.source_label} - ${a.source_event || a.source}`],
    ['Pipeline', escapeHtml(a.pipeline), a.pipeline],
    ['Environment', escapeHtml(a.environment), a.environment],
    ['Run', runCell, `${a.run_id || '-'} ${a.run_url || ''}`.trim()],
    ['Detail', escapeHtml(a.error_message || '-'), a.error_message || '-'],
    ['Fingerprint', escapeHtml(a.fingerprint), a.fingerprint],
    ['Alert id', escapeHtml(a.alert_id), String(a.alert_id)],
  ];
  const html = [
    `<h2>${escapeHtml(a.summary)}</h2>`,
    '<table cellpadding="4" style="border-collapse:collapse">',
    ...rows.map(([label, htmlValue], i) => `<tr${i % 2 ? '' : ' style="background:#f4f4f4"'}><th align="left">${label}</th><td>${htmlValue}</td></tr>`),
    '</table>',
    '<p>Sent by the n8n DataOps alert router. Repeats of this alert are suppressed for the de-duplication window.</p>',
  ].join('\n');
  const text = [a.summary, '', ...rows.map(([label, , plain]) => `${label}: ${plain}`)].join('\n');
  return { subject: `[${a.severity}] ${a.pipeline} ${verb(a)} in ${a.environment}`, html, text };
}

function build(row) {
  const a = {
    ...row.alert,
    alert_id: Number(row.alert_id),
    decision: row.decision,
    occurrence: Number(row.occurrence),
    is_replay: row.is_replay === true || row.is_replay === 'true',
  };
  a.action = !a.is_replay && NOTIFYING.has(a.decision) ? a.decision : 'NONE';
  a.slack = slackMessage(a);
  a.jira = { fields: jiraFields(a) };
  a.email = email(a);
  return a;
}

return $input.all().map((item) => ({ json: build(item.json) }));

parameters.query:
INSERT INTO alerting.delivery_log (alert_id, channel, status, external_ref, detail)
VALUES ($1, $2, $3, NULLIF($4, ''), $5)
RETURNING delivery_id, alert_id, channel, status, external_ref;
